/*
 * prog41_series_sum – reconstructed from the supplied binary.
 *
 * The original program expects exactly two integer command‑line arguments:
 *
 *   1. mode  – selects the series to evaluate
 *        1 :  Σ 1/k²          (Basel series)
 *        2 :  Σ (-1)^{k+1}/k  (alternating harmonic series)
 *        3 :  Σ 1/k           (harmonic series)
 *
 *   2. n     – the number of terms to sum (0 ≤ n ≤ 100 000)
 *
 * Behaviour
 * ----------
 *   * If fewer than two arguments are supplied → prints "NO_INPUT".
 *   * If either argument cannot be parsed as a non‑negative integer
 *     (or contains extra characters) → prints "BAD_INPUT".
 *   * If the mode is not 1, 2 or 3 → prints "BAD_MODE".
 *   * If n is larger than 100 000 → prints "OUT_OF_RANGE".
 *
 *   On success the program prints the value of the selected series,
 *   summed over the first *n* terms, with six digits after the decimal
 *   point (format "%.6f\n").
 *
 * The implementation below follows the logic observed in the decompiled
 * state‑machine, but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

/* Helper: parse a decimal integer and ensure the whole string is consumed. */
static int parse_int(const char *s, long *out)
{
    char *endptr = NULL;
    errno = 0;
    long v = strtol(s, &endptr, 10);

    /* strtol must have consumed the whole string and not overflow */
    if (errno != 0 || endptr == s || *endptr != '\0')
        return 0;               /* failure */

    *out = v;
    return 1;                   /* success */
}

int main(int argc, char *argv[])
{
    /* ---------- argument count check ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    long mode, n;
    if (!parse_int(argv[1], &mode) || !parse_int(argv[2], &n)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- range checks ---------- */
    if (mode < 1 || mode > 3) {
        puts("BAD_MODE");
        return 0;
    }

    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- series computation ---------- */
    double sum = 0.0;

    if (mode == 1) {                     /* Σ 1/k² */
        for (long k = 1; k <= n; ++k) {
            sum += 1.0 / ((double)k * (double)k);
        }
    } else if (mode == 2) {              /* Σ (-1)^{k+1} / k */
        for (long k = 1; k <= n; ++k) {
            double term = 1.0 / (double)k;
            if ((k & 1) == 0)            /* even k → negative term */
                term = -term;
            sum += term;
        }
    } else {                             /* mode == 3 : Σ 1/k */
        for (long k = 1; k <= n; ++k) {
            sum += 1.0 / (double)k;
        }
    }

    /* ---------- output ---------- */
    printf("%.6f\n", sum);
    return 0;
}
